"""Dual unit-response cells generated by primitive causal moves.

Given signed primitive displacements Phi, the response cell is the half-space
system <y,b><=1 for every b in Phi.  It is the polar of the primitive operation
polytope, but the causal interpretation comes first: every primitive move changes
the linear probe by at most one response unit.

This module records exact 3D integer/rational shadows for SC, FCC/D3, and scaled
BCC.  Euclidean Wigner-Seitz equality is an external comparison, not part of the
causal definition.  In particular BCC demonstrates that the primitive response
cell need not equal the full Euclidean Voronoi cell.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product

Vector3 = tuple[int, int, int]
Rational3 = tuple[Fraction, Fraction, Fraction]


def dot(vector: Vector3, point: Rational3) -> Fraction:
    return sum(Fraction(value) * coordinate for value, coordinate in zip(vector, point))


def sc_primitive_moves() -> tuple[Vector3, ...]:
    moves = []
    for axis in range(3):
        for sign in (-1, 1):
            vector = [0, 0, 0]
            vector[axis] = sign
            moves.append(tuple(vector))
    return tuple(moves)


def fcc_primitive_moves() -> tuple[Vector3, ...]:
    moves = []
    for zero in range(3):
        others = [index for index in range(3) if index != zero]
        for left in (-1, 1):
            for right in (-1, 1):
                vector = [0, 0, 0]
                vector[others[0]] = left
                vector[others[1]] = right
                moves.append(tuple(vector))
    return tuple(moves)


def bcc_primitive_moves() -> tuple[Vector3, ...]:
    return tuple(product((-1, 1), repeat=3))


def sc_response_vertices() -> tuple[Rational3, ...]:
    return tuple(tuple(Fraction(value) for value in signs) for signs in product((-1, 1), repeat=3))


def fcc_response_vertices() -> tuple[Rational3, ...]:
    axial = []
    for axis in range(3):
        for sign in (-1, 1):
            vector = [Fraction(0), Fraction(0), Fraction(0)]
            vector[axis] = Fraction(sign)
            axial.append(tuple(vector))
    corners = tuple(
        tuple(Fraction(sign, 2) for sign in signs)
        for signs in product((-1, 1), repeat=3)
    )
    return tuple(axial) + corners


def bcc_response_vertices() -> tuple[Rational3, ...]:
    axial = []
    for axis in range(3):
        for sign in (-1, 1):
            vector = [Fraction(0), Fraction(0), Fraction(0)]
            vector[axis] = Fraction(sign)
            axial.append(tuple(vector))
    return tuple(axial)


def point_satisfies_primitive_response_cell(
    point: Rational3,
    primitive_moves: tuple[Vector3, ...],
) -> bool:
    return all(dot(move, point) <= 1 for move in primitive_moves)


def active_primitive_constraints(
    point: Rational3,
    primitive_moves: tuple[Vector3, ...],
) -> tuple[Vector3, ...]:
    return tuple(move for move in primitive_moves if dot(move, point) == 1)


def response_vertex_profile(
    primitive_moves: tuple[Vector3, ...],
    vertices: tuple[Rational3, ...],
) -> tuple[int, tuple[int, ...]]:
    if not all(point_satisfies_primitive_response_cell(vertex, primitive_moves) for vertex in vertices):
        raise ValueError("declared vertices must satisfy every primitive response inequality")
    active = tuple(sorted(len(active_primitive_constraints(vertex, primitive_moves)) for vertex in vertices))
    return len(vertices), active


def three_dimensional_response_profiles() -> dict[str, tuple[int, tuple[int, ...]]]:
    return {
        "SC": response_vertex_profile(sc_primitive_moves(), sc_response_vertices()),
        "FCC": response_vertex_profile(fcc_primitive_moves(), fcc_response_vertices()),
        "BCC": response_vertex_profile(bcc_primitive_moves(), bcc_response_vertices()),
    }


def euclidean_voronoi_primitive_completeness_pressure_test() -> dict[str, tuple[int, int, bool]]:
    """External 3D comparison: `(primitive signed constraints, Voronoi facets, matches)`.

    SC and FCC Euclidean Wigner-Seitz cells are cut out by their nearest primitive
    directions (6 and 12 facets).  BCC has 8 nearest directions but its Euclidean
    Voronoi/Wigner-Seitz truncated octahedron has 14 facets: six second-neighbor
    constraints are additionally relevant.  The facet counts are external
    crystallographic facts and should remain cited as such in research prose.
    """
    data = {
        "SC": (6, 6),
        "FCC": (12, 12),
        "BCC": (8, 14),
    }
    return {name: (primitive, voronoi, primitive == voronoi) for name, (primitive, voronoi) in data.items()}
